#!/usr/bin/env bash
# СУДИТ: hooks/backlog-lib.sh scripts/backlog-refresh-readings.sh
# probe_D448.sh — проба пункта D448: `scripts/backlog-refresh-readings.sh` (и хук
#                 `hooks/backlog-reading-refresh.sh`, вызывающий тот же скрипт) записывает
#                 ПУСТОЕ показание, когда команда «Показание.» завершилась успешно (rc=0),
#                 но не вывела вообще ничего (ни stdout, ни stderr) — «не смог измерить»
#                 записывается как измеренное пустое значение.
# Результат: на команде, которая молча отвечает rc=0 без единого байта на выходе, строка
#            «Последнее показание» получает «НЕ ИЗМЕРЕНО: …», а не пустоту; настоящее
#            значение и настоящий отказ (rc!=0) пишутся как прежде.
# Проверка результата: bash hooks/tests/fixtures/probe_D448.sh даёт 0
#
# Коды: 0 — желаемое поведение соблюдено; 1 — дефект наблюдён (пустое показание);
#       2 — рамка не собралась (stderr называет, что).
# Механизм под судом собирается в СВОЁМ временном проекте: `backlog-refresh-readings.sh`
# читает CLAUDSOUL_REPO как корень проекта, ГДЕ ЛЕЖИТ BACKLOG.md (то же имя переменной, что
# у MECH), поэтому копия механизма кладётся в песочницу и зовётся из неё БЕЗ повторного
# экспорта CLAUDSOUL_REPO — приём как у probe_D427.sh/probe_D447.sh. Живой BACKLOG.md не
# читается никогда (свой файл в песочнице). Живой ~/.claude/hooks/state-lock-lib.sh —
# запасной путь механизма (:87), когда своей копии рядом нет; чтобы это не стало
# зависимостью от домашнего каталога, HOME на время вызова переназначается на пустой
# каталог песочницы, и запасной путь честно не находится.
set -uo pipefail
ROOT="$(cd "$(dirname "$0")/../../.." && pwd -P)"
MECH="${CLAUDSOUL_REPO:-$ROOT}"
[ -f "$MECH/scripts/backlog-refresh-readings.sh" ] || { echo "probe_D448: нет $MECH/scripts/backlog-refresh-readings.sh" >&2; exit 2; }
[ -f "$ROOT/hooks/backlog-lib.sh" ] || { echo "probe_D448: нет $ROOT/hooks/backlog-lib.sh" >&2; exit 2; }
command -v python3 >/dev/null 2>&1 || { echo "probe_D448: нет python3" >&2; exit 2; }
T=$(cd "$(mktemp -d)" && pwd -P) || { echo "probe_D448: нет временного каталога" >&2; exit 2; }
trap 'rm -rf "$T"' EXIT
P="$T/proj"; FAKE_HOME="$T/home"; mkdir -p "$P/scripts" "$P/hooks" "$FAKE_HOME"
cp "$MECH/scripts/backlog-refresh-readings.sh" "$P/scripts/" || { echo "probe_D448: копия механизма не удалась" >&2; exit 2; }
# backlog-lib.sh не патчится этим пунктом — берётся неизменным, живым.
cp "$ROOT/hooks/backlog-lib.sh" "$P/hooks/" || { echo "probe_D448: копия backlog-lib.sh не удалась" >&2; exit 2; }
# Правило исполнения «Показания» пересчёт берёт из своего дерева (`hooks/lib/bounded_run.py`, D1199).
mkdir -p "$P/hooks/lib" && cp "$ROOT/hooks/lib/bounded_run.py" "$ROOT/hooks/lib/backlog_cmd.py" "$P/hooks/lib/" \
    || { echo "probe_D448: копия hooks/lib/bounded_run.py не удалась" >&2; exit 2; }

reading_of() { grep -m1 'Последнее показание' "$P/BACKLOG.md" | sed 's/^[[:space:]]*//'; }

run_case() {  # run_case <команда показания> <старое-значение>
    cat > "$P/BACKLOG.md" <<EOF
- ☐ **D901** проба.
  **Показание.** \`$1\`
  **Последнее показание (2020-01-01).** $2
EOF
    # CLAUDSOUL_REPO переназначается на песочницу ЯВНО: снаружи он уже мог быть выставлен
    # зелёной стороной на каталог МЕХАНИЗМА ($MECH), а этот скрипт читает ту же переменную
    # как корень ПРОЕКТА (где лежит BACKLOG.md) — не переназначить здесь значило бы отдать
    # ему чужой каталог без BACKLOG.md, и он молча вышел бы кодом 0, ничего не пересчитав.
    # HOME переназначается на пустой каталог песочницы: запасной путь механизма к
    # state-lock-lib.sh (backlog-refresh-readings.sh:110) иначе нашёл бы ЖИВОЙ
    # ~/.claude/hooks/state-lock-lib.sh — без вреда результату (замок только УЛУЧШАЕТ
    # запись показания, при его отсутствии механизм работает как прежде), но и без права
    # заявлять, что живой ~/.claude не читается.
    ( cd "$P" && CLAUDSOUL_REPO="$P" HOME="$FAKE_HOME" bash scripts/backlog-refresh-readings.sh run ) >/dev/null 2>&1
}

# Положительный контроль 1: команда честно выводит значение — оно и записывается.
run_case 'printf "5 файлов"' "старое"
R=$(reading_of)
grep -q '5 файлов' <<< "$R" || { echo "probe_D448: контроль — настоящее значение не записалось: [$R]" >&2; exit 2; }

# Положительный контроль 2: команда падает (rc!=0) с текстом в stderr — уже даёт «НЕ ИЗМЕРЕНО»,
# это не предмет пункта, но рамка обязана оставаться исправной на нём.
run_case 'bash -c "echo boom 1>&2; exit 3"' "старое"
R=$(reading_of)
grep -q 'НЕ ИЗМЕРЕНО' <<< "$R" || { echo "probe_D448: контроль — падение (rc!=0) не дало «НЕ ИЗМЕРЕНО»: [$R]" >&2; exit 2; }
# Контроль 2 судит СЛОВО, а не только «НЕ ИЗМЕРЕНО»: первая редакция починки поставила новую
# ветку ВПЕРЕДИ ветки падения, и молча упавшая команда стала называться «не вывела ничего» —
# два состояния мира снова в одном канале, ровно корень пункта. Общая подстрока это пропускала.
grep -q 'упала (rc=3)' <<< "$R" || { echo "probe_D448: контроль — падение (rc=3) не названо падением: [$R]" >&2; exit 2; }

# Контроль 3 — ИСКЛЮЧЁННЫЙ случай пункта: rc=0 и пустой stdout при НЕПУСТОМ stderr. Пункт
# объявил его остающимся на прежнем пути (значение берётся у stderr), и охраны у этого
# обещания не было: подделка «пусто в stdout ⇒ НЕ ИЗМЕРЕНО» зеленила пробу, потеряв значение.
run_case 'bash -c "echo hi 1>&2; exit 0"' "старое"
R=$(reading_of)
grep -q 'hi' <<< "$R" || { echo "probe_D448: контроль — rc=0 с текстом в stderr потерял значение: [$R]" >&2; exit 2; }

# Контроль 4: вывод из ОДНИХ ПРОБЕЛОВ — это тот же «не вывела ничего», и различать его надо
# после `.strip()`. Подделка «not r.stdout and not r.stderr» (без обрезки) зеленила пробу и
# оставляла ровно дефект пункта: `" · ".join(...)` на пробельной строке даёт пустое значение.
run_case 'printf "  \n "' "старое"
R=$(reading_of)
grep -q 'НЕ ИЗМЕРЕНО' <<< "$R" || { echo "probe_D448: контроль — пробельный вывод записан не как «НЕ ИЗМЕРЕНО»: [$R]" >&2; exit 1; }

# Суд: команда отвечает rc=0 и не печатает НИ БАЙТА — ни в stdout, ни в stderr.
run_case 'true' "старое-значение"
R=$(reading_of)
[ -n "$R" ] || { echo "probe_D448: строка «Последнее показание» пропала целиком — рамка не собралась" >&2; exit 2; }
# Якорь терпит отступ сам (род E реестра: контрактная строка в пункте стоит с отступом), а классы —
# `[[:space:]]`: `\t` внутри скобок BSD sed читает как обратную черту и букву, а не табуляцию.
VALUE=$(sed 's/^[[:space:]]*\*\*Последнее показание[^*]*\*\*[[:space:]]*//' <<< "$R")
if [ -z "$VALUE" ]; then
    echo "probe_D448: дефект — команда rc=0 без вывода записана пустым показанием: [$R]" >&2
    exit 1
fi
grep -q 'НЕ ИЗМЕРЕНО' <<< "$VALUE" || { echo "probe_D448: значение не пусто, но и не «НЕ ИЗМЕРЕНО» — непредвиденный вид: [$R]" >&2; exit 2; }
exit 0
